={{ (() => {
  // One block per day: Mondays list Friday, Saturday and Sunday; other days list yesterday
  const days = $("Get search results").item.json.results;
  const blocks = days.flatMap((day, index) => [
    {
      type: "TextBlock",
      text: "Splunk license usage: " + day.report_date,
      wrap: true,
      // Leave a larger gap before every day after the first
      spacing: index === 0 ? "None" : "Large"
    },
    {
      type: "TextBlock",
      text: "Ingestion: " + Number(day.ingestion_gb).toFixed(2) + " GB of the 10 GB threshold",
      wrap: true,
      spacing: "None"
    }
  ]);
  // Teams Workflows webhooks expect an Adaptive Card wrapped in a message
  return {
    type: "message",
    attachments: [
      {
        contentType: "application/vnd.microsoft.card.adaptive",
        contentUrl: null,
        content: {
          "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
          type: "AdaptiveCard",
          version: "1.4",
          body: blocks
        }
      }
    ]
  };
})() }}

={{ (() => {
  // A failed step reports under "execution"; a failed schedule trigger reports under "trigger"
  const failure = $("On workflow error").item.json;
  const error = failure.execution?.error ?? failure.trigger?.error ?? {};
  const blocks = [
    {
      type: "TextBlock",
      text: failure.workflow.name + " failed",
      weight: "Bolder",
      wrap: true
    },
    {
      type: "TextBlock",
      text: "Step: " + (failure.execution?.lastNodeExecuted ?? "schedule trigger"),
      wrap: true,
      spacing: "Small"
    },
    {
      type: "TextBlock",
      text: "Error: " + (error.message ?? "no error message"),
      wrap: true,
      spacing: "None"
    }
  ];
  // Some errors carry extra detail, such as Splunk's own explanation
  if (error.description) {
    blocks.push({
      type: "TextBlock",
      text: "Details: " + error.description,
      wrap: true,
      spacing: "None"
    });
  }
  // Button to the failed run, when there is one
  const actions = failure.execution?.url
    ? [
        {
          type: "Action.OpenUrl",
          title: "Open the failed run",
          url: failure.execution.url
        }
      ]
    : [];
  // Teams Workflows webhooks expect an Adaptive Card wrapped in a message
  return {
    type: "message",
    attachments: [
      {
        contentType: "application/vnd.microsoft.card.adaptive",
        contentUrl: null,
        content: {
          "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
          type: "AdaptiveCard",
          version: "1.4",
          body: blocks,
          actions: actions
        }
      }
    ]
  };
})() }}
